// The port's own chaos floor of a whole recipe beside Blender's (a diagnostic of the distribution-class verdict,
// PORT_PLAN.md 5.3, 5.4): each seed generated by the port at draft quality at the reference's extent (the floor runs'
// call), as it is and with Blender's perturbation (a) of 5.4 (every float32 field of the level moved by one ulp at
// every op entry, up on a quarter of the cells and down on another quarter, default_rng([pattern, op call])), K
// patterns, and the main level's numbers (core/metrics.js: the judge's generic numbers, metrics.py's to rounding)
// beside the Blender floor run's base and its perturbed runs (run.json and p<k>/sample.json metrics_main). So each
// seed has two samples of the landform's spread over a one-ulp difference, one per edition: where they overlap, a
// band the port passes on fewer seeds than Blender is that spread, not the port; where the port's runs sit apart,
// the difference is the port's. With the band of each number (the Blender base verdict's lo and hi), the share of
// each edition's runs that pass it, seed by seed.
// JavaScript per cell here is test code (the perturbation and the bookkeeping).
//
//     deno run --no-config --no-lock --unstable-webgpu --allow-all eidoverse/terrain/tests/fluvial/port_floor.mjs
//         [--recipe fluvial_range] [--seeds 1,2,3,4] [--k 5]           (on a shared machine, behind $EIDO_GPU_WRAP)
//
// Writes tests/out/fluvial/port_floor_<recipe>.json.

import * as G from '../../core/gpu.js';
import { defaultRng } from '../../core/np_random.js';
import * as M from '../../core/metrics.js';
import * as RUN from '../../run.js';
import * as C from '../parity/_common.mjs';

const W = C.W;
const args = [...Deno.args];
const opt = (name, dflt) => { const i = args.indexOf(name); return i >= 0 ? args[i + 1] : dflt; };
const RECIPE = opt('--recipe', 'fluvial_range');
const SEEDS = opt('--seeds', '1,2,3,4').split(',').map(Number);
const K = Number(opt('--k', '5'));
const KEYS = ['relief_m', 'hypsometric_integral', 'slope_p50', 'slope_p90', 'slope_p99', 'frac_slope_lt5', 'spectrum_slope',
    'depression_area_frac', 'depression_count', 'anisotropy_4', 'anisotropy_8', 'cliff_pair_frac'];
// a recipe without a reference DEM is judged by its own criteria (recipes/meadow.js: slope p99 under 15 degrees, no
// pits): the share of each edition's runs that meet them
const CRITERIA = { meadow: (m) => m.slope_p99 < 15.0 && m.depression_count === 0 };

const F32 = new Float32Array(1), U32 = new Uint32Array(F32.buffer);
function nextafter32(v, up) {
    if (v === 0) return v;
    F32[0] = v;
    U32[0] += ((v > 0) === up) ? 1 : -1;
    return F32[0];
}

// the Blender floor run of (recipe, seed) under the key, else under a key of the same terrain code (judge_test.mjs)
function floorRunOfCode(recipe, seed) {
    const own = W.floorRun(recipe, seed);
    if (own) return own;
    const key = W.parityKeyDir();
    const code = (dir) => { const k = C.readJson(`${dir}/manifest.json`)?.key; return k ? `${k.field_hash}|${k.terrain_hash}` : null; };
    const mine = key ? code(key) : null;
    for (const k of W.parityKeys()) {
        const dir = `${k.dir}/${recipe}_s${seed}_draft/base`;
        if (mine && k.dir !== key && code(k.dir) === mine && W.exists(`${dir}/done.json`)) return dir;
    }
    return null;
}

const R = await G.init();
const registry = await import('../../recipes/index.js');
const { resolveCall } = await import('../../api.js');
const out = { recipe: RECIPE, k: K, seeds: {} };

for (const seed of SEEDS) {
    const base = floorRunOfCode(RECIPE, seed);
    const brun = base ? C.readJson(`${base}/run.json`) : null;
    const size = Number(brun?.size ?? 0) || null;
    const r = await resolveCall({ recipe: RECIPE, seed, quality: 'draft', size, cache: false, log: () => {} });
    if (r.recipe.prepare) await r.recipe.prepare(r.values, r.plan, { R, log: () => {} });
    const main = r.plan.findIndex((lv) => lv.role === 'main');
    const runs = [];
    for (let pattern = 0; pattern <= K; pattern++) {
        let call = 0;
        const getOp = async (name) => {
            const fn = await registry.getOp(name);
            if (pattern === 0) return fn;
            const wrapped = async (fields, level, params, sd, ctx) => {
                const rng = defaultRng([pattern, call++]);
                for (const k of Object.keys(fields).sort()) {
                    const f = fields[k];
                    if (!f || f.kind !== 'f32' || f.channels !== 1) continue;
                    const a = await R.read(f), u = rng.random(a.length), b = new Float32Array(a.length);
                    for (let i = 0; i < a.length; i++) b[i] = u[i] < 0.25 ? nextafter32(a[i], true) : u[i] >= 0.75 ? nextafter32(a[i], false) : a[i];
                    R.write(f, b);
                }
                return RUN.takesCtx(fn) ? fn(fields, level, params, sd, ctx) : fn(fields, level, params, sd);
            };
            wrapped.takesCtx = RUN.takesCtx(fn);
            if (fn.evolves !== undefined) wrapped.evolves = fn.evolves;
            if (fn.post !== undefined) wrapped.post = fn.post;
            return wrapped;
        };
        const t0 = performance.now();
        const made = await RUN.runLevels(r.plan, r.recipe, r.values, r.stages, { seed: r.seed, flatten: r.flatten, seaLevel: r.seaLevel,
            baseElevationM: r.baseElevationM, cache: false, info: {}, getOp, log: () => {}, runner: R });
        const m = await M.metrics(made[main].h, r.plan[main].cell);
        for (const f of made) for (const k of Object.keys(f)) f[k]?.destroy?.();
        const row = Object.fromEntries(KEYS.map((k) => [k, m[k]]));
        runs.push(row);
        console.log(`${RECIPE} s${seed} port ${pattern ? `pattern ${pattern}` : 'base'}: ${((performance.now() - t0) / 1000).toFixed(1)} s, ` +
            `spectrum slope ${row.spectrum_slope.toFixed(4)}, hypsometric ${row.hypsometric_integral.toFixed(4)}, frac < 5 deg ${row.frac_slope_lt5.toFixed(4)}`);
    }
    // Blender's base and perturbed runs of the seed
    const bruns = [];
    if (brun?.metrics_main) bruns.push(Object.fromEntries(KEYS.map((k) => [k, brun.metrics_main[k]])));
    for (let p = 1; p <= 9 && base; p++) {
        const s = C.readJson(`${base}/../p${p}/sample.json`);
        if (s?.metrics_main) bruns.push(Object.fromEntries(KEYS.map((k) => [k, s.metrics_main[k]?.[1]])));
    }
    // the bands of the Blender base verdict (lo, hi), and each edition's share of runs inside them
    const verdict = base ? C.readJson(`${base}/verdict.json`) : null;
    const bands = {};
    for (const row of verdict?.rows ?? []) if (row.passed !== null && row.passed !== undefined) bands[row.metric] = { lo: row.lo, hi: row.hi };
    const inside = (x, b) => (b.lo == null || x >= b.lo) && (b.hi == null || x <= b.hi);
    const stat = (xs) => {
        const v = xs.filter((x) => Number.isFinite(x));
        const mean = v.reduce((s, x) => s + x, 0) / Math.max(v.length, 1);
        const sd = Math.sqrt(v.reduce((s, x) => s + (x - mean) ** 2, 0) / Math.max(v.length - 1, 1));
        return { n: v.length, mean, sd, min: Math.min(...v), max: Math.max(...v) };
    };
    const per = {};
    for (const k of KEYS) {
        const p = runs.map((x) => x[k]), b = bruns.map((x) => x[k]);
        per[k] = { port: p, blender: b, port_stat: stat(p), blender_stat: stat(b) };
        if (bands[k]) {
            per[k].band = bands[k];
            per[k].port_pass = p.filter((x) => inside(x, bands[k])).length;
            per[k].blender_pass = b.filter((x) => inside(x, bands[k])).length;
        }
    }
    out.seeds[seed] = { blender_run: base, runs: runs.length, blender_runs: bruns.length, metrics: per };
    if (CRITERIA[RECIPE]) {
        const c = CRITERIA[RECIPE];
        out.seeds[seed].criteria = { port_meet: runs.filter(c).length, port: runs.length, blender_meet: bruns.filter(c).length, blender: bruns.length };
        console.log(`  the recipe's criteria met: port ${out.seeds[seed].criteria.port_meet} of ${runs.length}, Blender ` +
            `${out.seeds[seed].criteria.blender_meet} of ${bruns.length}`);
    }
    for (const k of ['spectrum_slope', 'hypsometric_integral', 'frac_slope_lt5', 'relief_m', ...(CRITERIA[RECIPE] ? ['slope_p99'] : [])]) {
        const q = per[k];
        console.log(`  ${k}: port ${C.sci(q.port_stat.mean, 3)} +- ${C.sci(q.port_stat.sd, 2)} [${C.sci(q.port_stat.min, 3)}, ${C.sci(q.port_stat.max, 3)}]` +
            `, Blender ${C.sci(q.blender_stat.mean, 3)} +- ${C.sci(q.blender_stat.sd, 2)} [${C.sci(q.blender_stat.min, 3)}, ${C.sci(q.blender_stat.max, 3)}]` +
            ` (${q.blender_stat.n} runs)` + (q.band ? `; in the band: port ${q.port_pass} of ${q.port.length}, Blender ${q.blender_pass} of ${q.blender.length}` : ''));
    }
}
Deno.writeTextFileSync(`${W.out('fluvial')}/port_floor_${RECIPE}.json`, JSON.stringify(out, null, 1));
G.shutdown();
